1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { wikiPages, sectionBody, firstSection, BULLET } from './lib.mjs';
3	
4	// The reader's entry point: every wiki page OPENS with a short bulleted list of
5	// what the research actually found, so a human gets the page's understanding
6	// without reading it end to end (the body stays the research record). Four
7	// always-wrong shapes are checkable, and only those — WHICH insights lead is
8	// judgment, owned by the prose and the growth worker:
9	//   * the header sits below another section (it isn't a header then);
10	//   * it carries no bullets (an empty promise at the top of the page);
11	//   * it has grown into a second body (more than MAX bullets);
12	//   * a bullet is a paragraph rather than a line (over MAX_CHARS).
13	// Prose lines in the section are flagged for the same reason: the contract is a
14	// scannable list, not a summary paragraph. Indented continuation lines belong to
15	// the bullet above them (judged as one block, like a Sources citation), so a
16	// hard-wrapped insight is never a false positive. Presence of the heading itself
17	// is page-sections' finding — never double-reported here.
18	//
19	// MAX_CHARS is deliberately tight — roughly one line of prose. A header is worth
20	// having only if it is faster to read than the page, and the failure mode in
21	// practice is a bullet that keeps qualifying itself. The nuance the qualifier
22	// wanted belongs in the body; the header states the finding plainly and stops.
23	const MAX = 7;
24	const MAX_CHARS = 140;
25	const NAME = 'Key insights';
26	const FIX = `open the page with "## ${NAME}" — up to ${MAX} bullets, each one finding stated plainly in a line (max ${MAX_CHARS} characters), together enough for a reader to understand what the research found without reading the body`;
27	
28	const rule = {
29	  id: 'product-wiki-key-insights',
30	  severity: 'blocking',
31	  doc: 'packs/product-wiki/README.md',
32	  description: 'Every wiki page opens with a succinct bulleted Key insights header',
33	  why: 'a research page whose findings can only be recovered by reading it end to end does not get read — the header is what makes a compiled wiki usable to a human',
34	
35	  run(ctx) {
36	    const out = [];
37	    for (const page of wikiPages(ctx.files)) {
38	      const text = ctx.read(page);
39	      if (text === null) continue;
40	      const section = sectionBody(text, NAME);
41	      if (section === null) continue; // page-sections owns the missing heading
42	
43	      const first = firstSection(text);
44	      if (first !== null && !new RegExp(`^${NAME}\\b`, 'i').test(first)) {
45	        out.push(finding(rule, {
46	          file: page,
47	          what: `the page opens with "## ${first}", not its "## ${NAME}" header`,
48	          fix: `move "## ${NAME}" above every other section — a header a reader reaches after the body is not a header`,
49	        }));
50	      }
51	
52	      let bullets = 0;
53	      for (let i = 0; i < section.length; i++) {
54	        const { line, text: t } = section[i];
55	        if (!BULLET.test(t)) {
56	          // Blank lines and a bullet's own indented continuation lines are the
57	          // list's own shape; anything else is prose in a list-only section.
58	          if (t.trim() !== '' && !/^\s+\S/.test(t)) {
59	            out.push(finding(rule, {
60	              file: page, line,
61	              what: `prose in the ${NAME} header: "${t.trim().slice(0, 80)}"`,
62	              fix: `the header is a bulleted list only — make it a bullet or move it into the page body below the "## ${NAME}" section`,
63	            }));
64	          }
65	          continue;
66	        }
67	        bullets += 1;
68	        let block = t;
69	        for (let j = i + 1; j < section.length && /^\s+\S/.test(section[j].text); j++) {
70	          block += ` ${section[j].text.trim()}`;
71	        }
72	        if (block.trim().length > MAX_CHARS) {
73	          out.push(finding(rule, {
74	            file: page, line,
75	            what: `${NAME} bullet runs ${block.trim().length} characters (max ${MAX_CHARS}): "${t.trim().slice(0, 80)}…"`,
76	            fix: 'cut it to the finding in plain words — the qualifiers, the supporting detail and the citation all live in the page body',
77	          }));
78	        }
79	      }
80	
81	      if (bullets === 0) {
82	        out.push(finding(rule, { file: page, what: `${NAME} header carries no bullets`, fix: FIX }));
83	      } else if (bullets > MAX) {
84	        out.push(finding(rule, {
85	          file: page,
86	          what: `${NAME} header carries ${bullets} bullets (max ${MAX}) — it has grown into a second body`,
87	          fix: `keep the ${MAX} that matter most; the rest is what the page body is for`,
88	        }));
89	      }
90	    }
91	    return out;
92	  },
93	};
94	
95	export default rule;
